begin;
select extensions.plan(20);
create temp table register_fixture(a uuid,b uuid,owner_id uuid,pro_user uuid,rec uuid,ro uuid,professional uuid,patient uuid,created uuid);
grant select on register_fixture to authenticated;
do $$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();o uuid:=gen_random_uuid();u uuid:=gen_random_uuid();r uuid:=gen_random_uuid();ro uuid:=gen_random_uuid();pr uuid:=gen_random_uuid();pa uuid:=gen_random_uuid();
begin
 insert into auth.users(id,email) select id,'register-'||id||'@example.test' from unnest(array[o,u,r,ro]) id;
 insert into public.businesses(id,name,slug,industry) values(a,'Synthetic register A','register-'||a,'other'),(b,'Synthetic register B','register-'||b,'other');
 update public.business_subscriptions set commercial_access_enabled=true,is_permanent=true,subscription_status='active',paid_until=null,grace_until=null,restricted_until=null where business_id in(a,b);
 insert into public.business_users(business_id,user_id,role,status,accepted_at) values(a,o,'owner','active',now()),(a,u,'professional','active',now()),(a,r,'reception','active',now()),(a,ro,'readonly','active',now());
 insert into public.professionals(id,business_id,name) values(pr,a,'Synthetic professional');
 insert into public.professional_users(business_id,professional_id,user_id) values(a,pr,u);
 insert into public.patients(id,business_id,owner_id,full_name,dni) values(pa,a,o,'Existing synthetic patient','83000001');
 insert into register_fixture values(a,b,o,u,r,ro,pr,pa,gen_random_uuid());
end $$;
select extensions.ok(not has_function_privilege('anon','public.register_patient_safely(uuid,uuid,text,text,text,text,text)','execute'),'anonymous cannot register');
select extensions.ok(not has_function_privilege('service_role','public.register_patient_safely(uuid,uuid,text,text,text,text,text)','execute'),'no administrative fallback contract');
set local role authenticated;
select set_config('request.jwt.claim.sub',(select pro_user::text from register_fixture),true);
select extensions.lives_ok($$select public.register_patient_safely(a,created,' New   synthetic patient ','83000002','123','123','+54123') from register_fixture$$,'professional registration succeeds atomically');
reset role;
select extensions.ok((select exists(select 1 from public.patients p where p.id=f.created and p.full_name='New synthetic patient' and p.owner_id=f.pro_user) from register_fixture f),'patient is persisted with actor provenance');
select extensions.ok((select exists(select 1 from public.professional_patient_links l where l.patient_id=f.created and l.professional_id=f.professional and l.is_active and l.created_by=f.pro_user) from register_fixture f),'professional link is persisted in same command');
set local role authenticated;
select set_config('request.jwt.claim.sub',(select pro_user::text from register_fixture),true);
select extensions.is((select (public.register_patient_safely(a,gen_random_uuid(),'Different input name','83000001','999','999','+54999')->>'patientId')::uuid from register_fixture),(select patient from register_fixture),'DNI resolves existing identity instead of overwriting');
reset role;
select extensions.is((select full_name from public.patients where id=(select patient from register_fixture)),'Existing synthetic patient','duplicate does not overwrite demographic data');
select extensions.ok((select exists(select 1 from public.professional_patient_links l where l.patient_id=f.patient and l.professional_id=f.professional and l.is_active) from register_fixture f),'duplicate gains caller link');
set local role authenticated;
reset role;
update public.professional_patient_links set is_active=false where patient_id=(select patient from register_fixture);
insert into public.professional_patient_links(business_id,professional_id,patient_id,is_active) select a,professional,patient,false from register_fixture;
set local role authenticated;
select set_config('request.jwt.claim.sub',(select pro_user::text from register_fixture),true);
select extensions.lives_ok($$select public.register_patient_safely(a,gen_random_uuid(),'Duplicate','83000001',null,null,null) from register_fixture$$,'multiple inactive historical links do not break restoration');
reset role;
select extensions.is((select count(*) from public.professional_patient_links where patient_id=(select patient from register_fixture) and is_active),1::bigint,'only one historical link reactivated');
set local role authenticated;
select set_config('request.jwt.claim.sub',(select rec::text from register_fixture),true);
select extensions.lives_ok($$select public.register_patient_safely(a,gen_random_uuid(),'New synthetic patient',null,'123','123','+54123') from register_fixture$$,'reception can create same name and phone');
select set_config('request.jwt.claim.sub',(select ro::text from register_fixture),true);
select extensions.throws_ok($$select public.register_patient_safely(a,gen_random_uuid(),'Denied',null,null,null,null) from register_fixture$$,'P0001','PATIENT_CREATE_DENIED','readonly direct command denied');
select set_config('request.jwt.claim.sub',(select pro_user::text from register_fixture),true);
select extensions.throws_ok($$select public.register_patient_safely(b,gen_random_uuid(),'Denied',null,null,null,null) from register_fixture$$,'P0001','PATIENT_CREATE_DENIED','foreign clinic denied');
reset role;
create function pg_temp.reject_register_link() returns trigger language plpgsql as $$begin if exists(select 1 from public.patients p where p.id=new.patient_id and p.dni='83000003') then raise exception 'SYNTHETIC_LINK_FAILURE'; end if;return new;end $$;
create trigger synthetic_register_link_failure before insert on public.professional_patient_links for each row execute function pg_temp.reject_register_link();
set local role authenticated;
select set_config('request.jwt.claim.sub',(select pro_user::text from register_fixture),true);
select extensions.throws_ok($$select public.register_patient_safely(a,gen_random_uuid(),'Rollback synthetic','83000003',null,null,null) from register_fixture$$,'P0001','SYNTHETIC_LINK_FAILURE','final link error aborts registration');
reset role;
select extensions.is((select count(*) from public.patients where business_id=(select a from register_fixture) and dni='83000003'),0::bigint,'no orphan patient after link failure');
update public.business_users set status='disabled',disabled_at=now() where business_id=(select a from register_fixture) and user_id=(select pro_user from register_fixture);
set local role authenticated;
select set_config('request.jwt.claim.sub',(select pro_user::text from register_fixture),true);
select extensions.throws_ok($$select public.register_patient_safely(a,gen_random_uuid(),'Denied',null,null,null,null) from register_fixture$$,'P0001','PATIENT_CREATE_DENIED','revoked membership denied');
reset role;
update public.business_users set status='active',disabled_at=null where business_id=(select a from register_fixture) and user_id=(select pro_user from register_fixture);
delete from public.professional_users where user_id=(select pro_user from register_fixture);
set local role authenticated;
select set_config('request.jwt.claim.sub',(select pro_user::text from register_fixture),true);
select extensions.throws_ok($$select public.register_patient_safely(a,gen_random_uuid(),'Denied',null,null,null,null) from register_fixture$$,'P0001','PROFESSIONAL_LINK_REQUIRED','missing professional assignment denied before patient insert');
reset role;
update public.business_subscriptions set commercial_access_enabled=false where business_id=(select a from register_fixture);
set local role authenticated;
select set_config('request.jwt.claim.sub',(select owner_id::text from register_fixture),true);
select extensions.throws_ok($$select public.register_patient_safely(a,gen_random_uuid(),'Denied',null,null,null,null) from register_fixture$$,'P0001','BUSINESS_ACCESS_RESTRICTED','commercial pause denied');
reset role;
select extensions.is((select count(*) from public.patients where business_id=(select a from register_fixture)),3::bigint,'only allowed patients persisted');
select extensions.is((select count(*) from public.patients where business_id=(select b from register_fixture)),0::bigint,'foreign clinic unchanged');
select * from extensions.finish();
rollback;
